-- EVT hook file for team_dock_formation_menu (VRFW.host handlers, docs/internal/lua-hosts.md). Graft rar_dock (rarity_dock.lua). Generated by research/scripts/menu_assemble.py; do not edit by hand.
local NORMAL_CARD_RARITY = 4
local TEAM_SET_INFO = 1033065575       -- (team set, team type, 8, slot) -> ok, status handle
local CHARA = 1131797651               -- CMND_GET_CHARA (hdl, 12) = the status' rarity
local SET_CHARA_RARITY = 1641888398    -- CMND_SET_CHARA_RARITY (hdl, rarity)
local LAST_TEAM_SLOT = 28
local DOCK_NUMBER_PARAM, DOCK_TYPE_PARAM = 3357163798, 4081600465

local function RarityRemovalApplies()
  local rules = rawget(_ENV, "ClassicCards")
  return type(rules) ~= "table" or type(rules.rarity_removal_applies) ~= "function" or rules.rarity_removal_applies()
end

-- every saved player (handle kind 0) of the team below the normal card rarity gets it
local function NormalizeTeam(teamSet, teamType)
  if not RarityRemovalApplies() then
    return 0
  end
  local done = 0
  for slot = 0, LAST_TEAM_SLOT do
    local ok, hdl = funcLuaCommand(TEAM_SET_INFO, teamSet, teamType, 8, slot)
    if ok and type(hdl) == "number" and hdl > 0 and math.floor(hdl / 4096) % 16 == 0 then
      local rarity = funcLuaCommand(CHARA, hdl, 12)
      if type(rarity) == "number" and rarity < NORMAL_CARD_RARITY then
        if funcLuaCommand(SET_CHARA_RARITY, hdl, NORMAL_CARD_RARITY) then
          done = done + 1
        end
      end
    end
  end
  if done > 0 then
    PRINT("EVT rarity: " .. done .. " player(s) raised to " .. NORMAL_CARD_RARITY)
  end
  return done
end

if VRFW.list_rows ~= nil then
  VRFW.list_rows.hide(VRFW.list_rows.PLAYER_COMMANDS, {id = "ClassicCards.hide_rarity_up",
    row = VRFW.list_rows.PLAYER_COMMAND.RARITY_UP, when = RarityRemovalApplies})
end

if VRFW.host ~= nil then
  local function ScriptLocal(name)
    local host = VRFW.host.hosts and VRFW.host.hosts["team_dock_formation_menu"]
    if host == nil or host.L == nil then
      return 0
    end
    local ok, value = pcall(function() return host.L[name] end)
    return ok and type(value) == "number" and value or 0
  end
  VRFW.host.on("team_dock_formation_menu", "OnInit", {id = "ClassicCards.normalize_team", phase = "before",
    fn = function()
      local dockNumber, dockType = ScriptLocal("n"), ScriptLocal("n10")
      if VRFW.param.has(DOCK_NUMBER_PARAM) then
        dockNumber = VRFW.param.get(DOCK_NUMBER_PARAM) or 0
      end
      if VRFW.param.has(DOCK_TYPE_PARAM) then
        dockType = VRFW.param.get(DOCK_TYPE_PARAM) or 0
      end
      NormalizeTeam(dockNumber, dockType)
    end})
end
